verus! {

pub trait Inv {
    spec fn inv(self) -> bool;
}

impl<T: Inv> Inv for Option<T> {
    open spec fn inv(self) -> bool {
        match self {
            Some(t) => t.inv(),
            None => true,
        }
    }
}

